<?php include '../includes/header.php';require_admin();$r=mysqli_query($conn,"SELECT id,name,email,role,institution_type,institution_code,status,approval_status,created_at,last_login_at FROM users ORDER BY id DESC");?>
<div class="page-head"><div><p class="eyebrow">ADMINISTRATION</p><h1>Users & Approvals</h1><p class="muted">Approve registrations, control access and assign operational roles.</p></div></div>
<div class="card table-wrap"><table><tr><th>User</th><th>Role</th><th>Institution</th><th>Status</th><th>Approval</th><th>Last login</th><th>Actions</th></tr><?php while($x=mysqli_fetch_assoc($r)):?><tr><td><b><?=e($x['name'])?></b><br><small><?=e($x['email'])?></small></td><td><form method="post" action="user_action.php" class="inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=$x['id']?>"><select name="role" onchange="this.form.submit()"><option value="staff" <?=$x['role']==='staff'?'selected':''?>>Clerk / Staff</option><option value="authorized_staff" <?=$x['role']==='authorized_staff'?'selected':''?>>Authorized Clerk</option><option value="sub_officer" <?=$x['role']==='sub_officer'?'selected':''?>>Sub Officer</option><option value="school_superintendent" <?=$x['role']==='school_superintendent'?'selected':''?>>Ashram Superintendent</option><option value="hostel_superintendent" <?=$x['role']==='hostel_superintendent'?'selected':''?>>Wastigruh Superintendent</option><option value="admin" <?=$x['role']==='admin'?'selected':''?>>Admin</option></select><input type="hidden" name="action" value="set_role"></form></td><td><?=e($x['institution_type'].' · '.$x['institution_code'])?></td><td><?=e($x['status'])?></td><td><?=e($x['approval_status'])?></td><td><?=e($x['last_login_at']?:'Never')?></td><td><form method="post" action="user_action.php" class="inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=$x['id']?>"><?php if($x['approval_status']==='pending'):?><button name="action" value="approve">Approve</button><button name="action" value="reject" class="secondary">Reject</button><?php elseif($x['status']==='active' && $x['id']!=user()['id']):?><button name="action" value="block" class="danger-btn">Block</button><?php elseif($x['status']==='blocked'):?><button name="action" value="unblock">Unblock</button><?php endif;?></form></td></tr><?php endwhile;?></table></div><?php include '../includes/footer.php';?>
